window.REFERENCE_DATA = {"tabs":[{"key":"terminology","label":"Medical Terminology"},{"key":"labs","label":"Lab Reference Values"},{"key":"formulas","label":"Dose Calculation Formulas"},{"key":"interactions","label":"Drug Interactions"},{"key":"pregnancy","label":"Pregnancy & Lactation"},{"key":"highalert","label":"High-Alert Medications"},{"key":"antidotes","label":"Common Antidotes"},{"key":"renalhepatic","label":"Renal & Hepatic Adjustment"},{"key":"suffixes","label":"Drug Suffixes / Stems"},{"key":"induced","label":"Drug-Induced Conditions"},{"key":"tdm","label":"Therapeutic Drug Monitoring"}],"panels":{"terminology":"<div>\n<nav class=\"section-nav\">\n<strong>Jump to section</strong>\n<a href=\"#dosing-abbr\">Dosing &amp; Frequency</a>\n<a href=\"#route-abbr\">Routes of Administration</a>\n<a href=\"#form-abbr\">Dosage Forms</a>\n<a href=\"#unit-abbr\">Units &amp; Measures</a>\n<a href=\"#clinical-abbr\">Clinical / Diagnostic</a>\n<a href=\"#chart-abbr\">Chart &amp; Order Abbreviations</a>\n</nav>\n<section class=\"group\" id=\"dosing-abbr\">\n<h2>Dosing &amp; Frequency</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Abbreviation</th><th>Meaning</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">qd / od</td><td>once daily</td></tr>\n<tr><td class=\"abbr\">bid</td><td>twice daily</td></tr>\n<tr><td class=\"abbr\">tid</td><td>three times daily</td></tr>\n<tr><td class=\"abbr\">qid</td><td>four times daily</td></tr>\n<tr><td class=\"abbr\">q4h / q6h / q8h / q12h</td><td>every 4 / 6 / 8 / 12 hours</td></tr>\n<tr><td class=\"abbr\">qod</td><td>every other day</td></tr>\n<tr><td class=\"abbr\">qam / qpm</td><td>every morning / every evening</td></tr>\n<tr><td class=\"abbr\">hs</td><td>at bedtime (hora somni)</td></tr>\n<tr><td class=\"abbr\">ac</td><td>before meals (ante cibum)</td></tr>\n<tr><td class=\"abbr\">pc</td><td>after meals (post cibum)</td></tr>\n<tr><td class=\"abbr\">prn</td><td>as needed (pro re nata)</td></tr>\n<tr><td class=\"abbr\">stat</td><td>immediately</td></tr>\n<tr><td class=\"abbr\">SOS</td><td>if necessary (si opus sit)</td></tr>\n<tr><td class=\"abbr\">Rx</td><td>prescription / treatment</td></tr>\n<tr><td class=\"abbr\">Sig</td><td>directions for use (signa)</td></tr>\n<tr><td class=\"abbr\">NPO</td><td>nothing by mouth (nil per os)</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"route-abbr\">\n<h2>Routes of Administration</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Abbreviation</th><th>Meaning</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">PO</td><td>by mouth (per os)</td></tr>\n<tr><td class=\"abbr\">IV</td><td>intravenous</td></tr>\n<tr><td class=\"abbr\">IM</td><td>intramuscular</td></tr>\n<tr><td class=\"abbr\">SC / SQ</td><td>subcutaneous</td></tr>\n<tr><td class=\"abbr\">SL</td><td>sublingual</td></tr>\n<tr><td class=\"abbr\">PR</td><td>per rectum</td></tr>\n<tr><td class=\"abbr\">PV</td><td>per vagina</td></tr>\n<tr><td class=\"abbr\">top.</td><td>topical</td></tr>\n<tr><td class=\"abbr\">inh.</td><td>inhalation</td></tr>\n<tr><td class=\"abbr\">ID</td><td>intradermal</td></tr>\n<tr><td class=\"abbr\">IT</td><td>intrathecal</td></tr>\n<tr><td class=\"abbr\">NG</td><td>nasogastric (tube)</td></tr>\n<tr><td class=\"abbr\">buc.</td><td>buccal</td></tr>\n<tr><td class=\"abbr\">oph.</td><td>ophthalmic</td></tr>\n<tr><td class=\"abbr\">otic</td><td>ear</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"form-abbr\">\n<h2>Dosage Forms</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Abbreviation</th><th>Meaning</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">tab</td><td>tablet</td></tr>\n<tr><td class=\"abbr\">cap</td><td>capsule</td></tr>\n<tr><td class=\"abbr\">syr</td><td>syrup</td></tr>\n<tr><td class=\"abbr\">susp</td><td>suspension</td></tr>\n<tr><td class=\"abbr\">sol</td><td>solution</td></tr>\n<tr><td class=\"abbr\">supp</td><td>suppository</td></tr>\n<tr><td class=\"abbr\">ung</td><td>ointment (unguentum)</td></tr>\n<tr><td class=\"abbr\">cr.</td><td>cream</td></tr>\n<tr><td class=\"abbr\">lot.</td><td>lotion</td></tr>\n<tr><td class=\"abbr\">gtt</td><td>drop (gutta)</td></tr>\n<tr><td class=\"abbr\">ER / XR / SR</td><td>extended release / sustained release</td></tr>\n<tr><td class=\"abbr\">DR</td><td>delayed release (enteric coated)</td></tr>\n<tr><td class=\"abbr\">IR</td><td>immediate release</td></tr>\n<tr><td class=\"abbr\">MDI</td><td>metered dose inhaler</td></tr>\n<tr><td class=\"abbr\">DPI</td><td>dry powder inhaler</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"unit-abbr\">\n<h2>Units &amp; Measures</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Abbreviation</th><th>Meaning</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">mg / mcg (\u00b5g)</td><td>milligram / microgram</td></tr>\n<tr><td class=\"abbr\">g / kg</td><td>gram / kilogram</td></tr>\n<tr><td class=\"abbr\">mL / L</td><td>milliliter / liter</td></tr>\n<tr><td class=\"abbr\">IU</td><td>international unit</td></tr>\n<tr><td class=\"abbr\">mEq</td><td>milliequivalent</td></tr>\n<tr><td class=\"abbr\">mmol</td><td>millimole</td></tr>\n<tr><td class=\"abbr\">%w/v, %v/v, %w/w</td><td>percent weight/volume, volume/volume, weight/weight</td></tr>\n<tr><td class=\"abbr\">gtt/min</td><td>drops per minute</td></tr>\n<tr><td class=\"abbr\">BSA</td><td>body surface area (m\u00b2)</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"clinical-abbr\">\n<h2>Clinical / Diagnostic Abbreviations</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Abbreviation</th><th>Meaning</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">HTN</td><td>hypertension</td></tr>\n<tr><td class=\"abbr\">DM</td><td>diabetes mellitus</td></tr>\n<tr><td class=\"abbr\">CHF</td><td>congestive heart failure</td></tr>\n<tr><td class=\"abbr\">COPD</td><td>chronic obstructive pulmonary disease</td></tr>\n<tr><td class=\"abbr\">CKD / AKI</td><td>chronic kidney disease / acute kidney injury</td></tr>\n<tr><td class=\"abbr\">MI</td><td>myocardial infarction</td></tr>\n<tr><td class=\"abbr\">CVA</td><td>cerebrovascular accident (stroke)</td></tr>\n<tr><td class=\"abbr\">UTI</td><td>urinary tract infection</td></tr>\n<tr><td class=\"abbr\">DVT / PE</td><td>deep vein thrombosis / pulmonary embolism</td></tr>\n<tr><td class=\"abbr\">GERD</td><td>gastroesophageal reflux disease</td></tr>\n<tr><td class=\"abbr\">RA</td><td>rheumatoid arthritis</td></tr>\n<tr><td class=\"abbr\">COPD exacerbation</td><td>acute worsening of COPD symptoms</td></tr>\n<tr><td class=\"abbr\">Dx / Rx / Tx</td><td>diagnosis / prescription / treatment</td></tr>\n<tr><td class=\"abbr\">Hx</td><td>history</td></tr>\n<tr><td class=\"abbr\">Sx</td><td>symptoms</td></tr>\n<tr><td class=\"abbr\">Fx</td><td>fracture</td></tr>\n<tr><td class=\"abbr\">c/o</td><td>complains of</td></tr>\n<tr><td class=\"abbr\">wnl</td><td>within normal limits</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"chart-abbr\">\n<h2>Chart &amp; Order Abbreviations</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Abbreviation</th><th>Meaning</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">D/C</td><td>discontinue / discharge</td></tr>\n<tr><td class=\"abbr\">BID/PRN</td><td>twice daily as needed</td></tr>\n<tr><td class=\"abbr\">q.s.</td><td>a sufficient quantity (quantum sufficiat)</td></tr>\n<tr><td class=\"abbr\">ad</td><td>up to / to make</td></tr>\n<tr><td class=\"abbr\">aa</td><td>of each (ana)</td></tr>\n<tr><td class=\"abbr\">disp.</td><td>dispense</td></tr>\n<tr><td class=\"abbr\">non rep. / NR</td><td>do not repeat (no refills)</td></tr>\n<tr><td class=\"abbr\">rep.</td><td>repeat</td></tr>\n<tr><td class=\"abbr\">M.</td><td>mix (misce)</td></tr>\n<tr><td class=\"abbr\">ft.</td><td>let it be made (fiat)</td></tr>\n</tbody>\n</table>\n</section>\n</div>","labs":"<div>\n<nav class=\"section-nav\">\n<strong>Jump to section</strong>\n<a href=\"#electrolytes\">Electrolytes</a>\n<a href=\"#renal\">Renal Function (RFT)</a>\n<a href=\"#liver\">Liver Function (LFT)</a>\n<a href=\"#hematology\">Hematology</a>\n<a href=\"#lipid\">Lipid Panel</a>\n<a href=\"#glucose\">Glucose / Endocrine</a>\n<a href=\"#thyroid\">Thyroid</a>\n<a href=\"#coag\">Coagulation</a>\n<a href=\"#other-labs\">Other Common Labs</a>\n</nav>\n<div class=\"tip\">\n    Reference ranges below are commonly cited adult ranges compiled from standard clinical\n    chemistry/hematology references (values vary by laboratory, analyzer, age, sex, and\n    population. Always confirm against the reporting lab's printed reference range).\n  </div>\n<section class=\"group\" id=\"electrolytes\">\n<h2>Electrolytes</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>Sodium (Na\u207a)</td><td>135\u2013145 mEq/L</td></tr>\n<tr><td>Potassium (K\u207a)</td><td>3.5\u20135.0 mEq/L</td></tr>\n<tr><td>Chloride (Cl\u207b)</td><td>96\u2013106 mEq/L</td></tr>\n<tr><td>Bicarbonate (HCO\u2083\u207b)</td><td>22\u201328 mEq/L</td></tr>\n<tr><td>Calcium, total</td><td>8.5\u201310.2 mg/dL</td></tr>\n<tr><td>Ionized calcium</td><td>4.6\u20135.3 mg/dL</td></tr>\n<tr><td>Magnesium</td><td>1.7\u20132.2 mg/dL</td></tr>\n<tr><td>Phosphate</td><td>2.5\u20134.5 mg/dL</td></tr>\n<tr><td>Anion gap</td><td>8\u201316 mEq/L</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"renal\">\n<h2>Renal Function (RFT)</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>Blood urea nitrogen (BUN)</td><td>7\u201320 mg/dL</td></tr>\n<tr><td>Serum creatinine (SCr)</td><td>0.6\u20131.2 mg/dL</td></tr>\n<tr><td>eGFR</td><td>&gt;90 mL/min/1.73m\u00b2 (normal)</td></tr>\n<tr><td>BUN:Creatinine ratio</td><td>10:1 to 20:1</td></tr>\n<tr><td>Uric acid</td><td>3.5\u20137.2 mg/dL</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"liver\">\n<h2>Liver Function (LFT)</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>ALT (SGPT)</td><td>7\u201356 U/L</td></tr>\n<tr><td>AST (SGOT)</td><td>10\u201340 U/L</td></tr>\n<tr><td>Alkaline phosphatase (ALP)</td><td>44\u2013147 U/L</td></tr>\n<tr><td>Total bilirubin</td><td>0.1\u20131.2 mg/dL</td></tr>\n<tr><td>Direct (conjugated) bilirubin</td><td>0.0\u20130.3 mg/dL</td></tr>\n<tr><td>Albumin</td><td>3.4\u20135.4 g/dL</td></tr>\n<tr><td>Total protein</td><td>6.0\u20138.3 g/dL</td></tr>\n<tr><td>GGT</td><td>8\u201361 U/L (male), 5\u201336 U/L (female)</td></tr>\n<tr><td>INR (baseline)</td><td>0.8\u20131.1</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"hematology\">\n<h2>Hematology (CBC)</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>Hemoglobin (Hgb)</td><td>13.5\u201317.5 g/dL (male), 12.0\u201315.5 g/dL (female)</td></tr>\n<tr><td>Hematocrit (Hct)</td><td>38.8\u201350% (male), 34.9\u201344.5% (female)</td></tr>\n<tr><td>WBC count</td><td>4.5\u201311.0 \u00d7 10\u00b3/\u00b5L</td></tr>\n<tr><td>Platelet count</td><td>150\u2013450 \u00d7 10\u00b3/\u00b5L</td></tr>\n<tr><td>RBC count</td><td>4.7\u20136.1 \u00d7 10\u2076/\u00b5L (male), 4.2\u20135.4 \u00d7 10\u2076/\u00b5L (female)</td></tr>\n<tr><td>MCV</td><td>80\u2013100 fL</td></tr>\n<tr><td>Ferritin</td><td>12\u2013300 ng/mL (male), 12\u2013150 ng/mL (female)</td></tr>\n<tr><td>Serum iron</td><td>60\u2013170 \u00b5g/dL</td></tr>\n<tr><td>TIBC</td><td>240\u2013450 \u00b5g/dL</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"lipid\">\n<h2>Lipid Panel</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>Total cholesterol</td><td>&lt;200 mg/dL (desirable)</td></tr>\n<tr><td>LDL cholesterol</td><td>&lt;100 mg/dL (optimal)</td></tr>\n<tr><td>HDL cholesterol</td><td>&gt;40 mg/dL (male), &gt;50 mg/dL (female)</td></tr>\n<tr><td>Triglycerides</td><td>&lt;150 mg/dL</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"glucose\">\n<h2>Glucose / Endocrine</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>Fasting plasma glucose</td><td>70\u2013100 mg/dL</td></tr>\n<tr><td>Random glucose</td><td>&lt;140 mg/dL</td></tr>\n<tr><td>HbA1c</td><td>&lt;5.7% (normal), 5.7\u20136.4% (prediabetes), \u22656.5% (diabetes)</td></tr>\n<tr><td>Fasting insulin</td><td>2.6\u201324.9 \u00b5IU/mL</td></tr>\n<tr><td>Cortisol (AM)</td><td>6.2\u201319.4 \u00b5g/dL</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"thyroid\">\n<h2>Thyroid</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>TSH</td><td>0.4\u20134.0 mIU/L</td></tr>\n<tr><td>Free T4</td><td>0.8\u20131.8 ng/dL</td></tr>\n<tr><td>Free T3</td><td>2.3\u20134.2 pg/mL</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"coag\">\n<h2>Coagulation</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>PT (Prothrombin time)</td><td>11\u201313.5 sec</td></tr>\n<tr><td>aPTT</td><td>25\u201335 sec</td></tr>\n<tr><td>INR</td><td>0.8\u20131.1 (2.0\u20133.0 therapeutic on warfarin, indication-dependent)</td></tr>\n<tr><td>D-dimer</td><td>&lt;0.50 \u00b5g/mL FEU</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"other-labs\">\n<h2>Other Common Labs</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Test</th><th>Reference Range</th></tr></thead>\n<tbody>\n<tr><td>Serum osmolality</td><td>275\u2013295 mOsm/kg</td></tr>\n<tr><td>CRP</td><td>&lt;3.0 mg/L</td></tr>\n<tr><td>ESR</td><td>0\u201315 mm/hr (male), 0\u201320 mm/hr (female)</td></tr>\n<tr><td>Lactate</td><td>0.5\u20132.2 mmol/L</td></tr>\n<tr><td>Ammonia</td><td>15\u201345 \u00b5g/dL</td></tr>\n<tr><td>Vitamin D (25-OH)</td><td>30\u2013100 ng/mL</td></tr>\n<tr><td>Vitamin B12</td><td>200\u2013900 pg/mL</td></tr>\n</tbody>\n</table>\n</section>\n</div>","formulas":"<div>\n<nav class=\"section-nav\">\n<strong>Jump to section</strong>\n<a href=\"#basic\">Basic Dosage</a>\n<a href=\"#iv\">IV Calculations</a>\n<a href=\"#dilution\">Dilution &amp; Concentration</a>\n<a href=\"#advanced\">Advanced Clinical</a>\n<a href=\"#compounding\">Compounding</a>\n<a href=\"#pk\">Pharmacokinetics</a>\n<a href=\"#peds\">Pediatric &amp; Geriatric</a>\n<a href=\"#misc\">Miscellaneous</a>\n</nav>\n<section class=\"group\" id=\"basic\">\n<h2>1. Basic Dosage Calculations</h2>\n<h3>a. Dose Based on Weight (mg/kg)</h3>\n<div class=\"formula-box searchable\">Dose (mg) = Weight (kg) \u00d7 Dose (mg/kg)</div>\n<div class=\"source-line\">Source: standard weight-based dosing method. Remington: The Science and Practice of Pharmacy, \"Pharmaceutical Calculations\" chapter</div>\n<h3>b. Dose Based on BSA</h3>\n<div class=\"formula-box searchable\">Dose (mg) = BSA (m\u00b2) \u00d7 Dose (mg/m\u00b2)</div>\n<div class=\"source-line\">Source: standard BSA-based dosing, widely used for chemotherapeutic agents. Remington: The Science and Practice of Pharmacy</div>\n<h3>c. Quantity to Dispense (Q.T.D.)</h3>\n<div class=\"formula-box searchable\">Q.T.D. = (Dose required \u00d7 Number of doses) / Strength per unit</div>\n<div class=\"source-line\">Source: standard pharmaceutical compounding/dispensing calculation. Remington: The Science and Practice of Pharmacy</div>\n</section>\n<section class=\"group\" id=\"iv\">\n<h2>2. Intravenous (IV) Calculations</h2>\n<h3>a. IV Flow Rate (mL/hr)</h3>\n<div class=\"formula-box searchable\">Flow Rate (mL/hr) = Total Volume (mL) / Time (hr)</div>\n<h3>b. IV Drip Rate (gtt/min)</h3>\n<div class=\"formula-box searchable\">Drip Rate (gtt/min) = [Total Volume (mL) \u00d7 Drop Factor (gtt/mL)] / Time (min)</div>\n<h3>c. Infusion Time</h3>\n<div class=\"formula-box searchable\">Time (hr) = Total Volume (mL) / Flow Rate (mL/hr)</div>\n<h3>d. Concentration of Infusion</h3>\n<div class=\"formula-box searchable\">Concentration = Amount of Drug / Total Volume (mL)</div>\n<div class=\"source-line\">Source: standard IV administration calculations. ASHP's \"Handbook on Injectable Drugs\"; Remington: The Science and Practice of Pharmacy</div>\n</section>\n<section class=\"group\" id=\"dilution\">\n<h2>3. Dilution &amp; Concentration</h2>\n<h3>a. Dilution Equation</h3>\n<div class=\"formula-box searchable\">C\u2081V\u2081 = C\u2082V\u2082</div>\n<div class=\"source-line\">Source: standard dilution law used throughout pharmaceutical and analytical chemistry. Remington: The Science and Practice of Pharmacy</div>\n<h3>b. Alligation Method</h3>\n<div class=\"where\">\n<div>C\u2081 = higher strength, C\u2082 = lower strength, C\u2093 = desired strength</div>\n<div>P\u2081 = C\u2093 \u2212 C\u2082 (parts of higher strength), P\u2082 = C\u2081 \u2212 C\u2093 (parts of lower strength)</div>\n<div>Ratio = P\u2081 : P\u2082</div>\n</div>\n<div class=\"source-line\">Source: classical alligation alternate method. Remington: The Science and Practice of Pharmacy, \"Pharmaceutical Calculations\" chapter</div>\n</section>\n<section class=\"group\" id=\"advanced\">\n<h2>4. Advanced Clinical Calculations</h2>\n<h3>a. Creatinine Clearance. Cockcroft-Gault</h3>\n<div class=\"formula-box searchable\">CrCl (mL/min) = [(140 \u2212 age) \u00d7 weight (kg)] / [72 \u00d7 SCr (mg/dL)] \u00d7 (0.85 if female)</div>\n<div class=\"source-line\">Source: Cockcroft DW, Gault MH. \"Prediction of creatinine clearance from serum creatinine.\" Nephron. 1976;16(1):31\u201341.</div>\n<h3>b. Ideal Body Weight (IBW). Devine formula</h3>\n<div class=\"formula-box searchable\">\n      Male: IBW = 50 kg + 2.3 kg \u00d7 (height in inches \u2212 60)<br/>\n      Female: IBW = 45.5 kg + 2.3 kg \u00d7 (height in inches \u2212 60)\n    </div>\n<div class=\"source-line\">Source: Devine BJ. \"Gentamicin therapy.\" Drug Intelligence &amp; Clinical Pharmacy. 1974;8:650\u2013655.</div>\n<h3>c. Adjusted Body Weight (ABW)</h3>\n<div class=\"formula-box searchable\">ABW (kg) = IBW + 0.4 \u00d7 (Actual BW \u2212 IBW)</div>\n<div class=\"source-line\">Source: correction factor (0.4) commonly applied in aminoglycoside/obesity dosing guidelines. See ASHP therapeutic drug monitoring guidance and clinical pharmacokinetics references.</div>\n<h3>d. Body Mass Index (BMI)</h3>\n<div class=\"formula-box searchable\">BMI (kg/m\u00b2) = weight (kg) / [height (m)]\u00b2</div>\n<div class=\"source-line\">Source: Quetelet index, adopted by WHO as the standard BMI definition. World Health Organization, \"Obesity: preventing and managing the global epidemic\" (WHO Technical Report Series).</div>\n<h3>e. mEq to mg Conversion</h3>\n<div class=\"formula-box searchable\">mg = mEq \u00d7 (Molecular Weight (mg) / Valence)</div>\n<div class=\"source-line\">Source: standard electrolyte conversion, based on definition of milliequivalent. Remington: The Science and Practice of Pharmacy</div>\n<h3>f. Serum Osmolarity</h3>\n<div class=\"formula-box searchable\">Osmolarity (mOsm/L) = 2 \u00d7 [Na\u207a] + [Glucose (mg/dL)]/18 + [BUN (mg/dL)]/2.8</div>\n<div class=\"source-line\">Source: standard clinical chemistry estimation formula. Widely cited in clinical chemistry and critical care references (e.g., Harrison's Principles of Internal Medicine).</div>\n</section>\n<section class=\"group\" id=\"compounding\">\n<h2>5. Compounding Calculations</h2>\n<h3>a. Percentage Strength</h3>\n<div class=\"formula-box searchable\">% w/v = [Weight of solute (g) / Volume of solution (mL)] \u00d7 100</div>\n<div class=\"formula-box searchable\">% v/v = [Volume of solute (mL) / Volume of solution (mL)] \u00d7 100</div>\n<div class=\"formula-box searchable\">% w/w = [Weight of solute (g) / Weight of solution (g)] \u00d7 100</div>\n<h3>b. Ratio Strength</h3>\n<div class=\"formula-box searchable\">1 in N = 1/N (1 part solute in N parts solution)</div>\n<div class=\"formula-box searchable\">N : 1 = N/1 (N parts solute in 1 part solution)</div>\n<div class=\"source-line\">Source: USP General Chapter &lt;795&gt; Pharmaceutical Compounding \u2013 Nonsterile Preparations; Remington: The Science and Practice of Pharmacy</div>\n</section>\n<section class=\"group\" id=\"pk\">\n<h2>6. Pharmacokinetic Calculations</h2>\n<h3>a. Half-Life (t\u00bd)</h3>\n<div class=\"formula-box searchable\">t\u00bd = 0.693 \u00d7 (Vd / CL)</div>\n<h3>b. Loading Dose (LD)</h3>\n<div class=\"formula-box searchable\">LD = (C_target \u00d7 Vd) / F</div>\n<h3>c. Maintenance Dose (MD)</h3>\n<div class=\"formula-box searchable\">MD = (C_target \u00d7 CL \u00d7 \u03c4) / F</div>\n<h3>d. Area Under the Curve (AUC)</h3>\n<div class=\"formula-box searchable\">AUC = (F \u00d7 Dose) / CL</div>\n<div class=\"source-line\">Source: standard one-compartment pharmacokinetic model equations. Winter ME, \"Basic Clinical Pharmacokinetics,\" Lippincott Williams &amp; Wilkins.</div>\n</section>\n<section class=\"group\" id=\"peds\">\n<h2>7. Pediatric &amp; Geriatric Dosing</h2>\n<h3>a. Young's Rule</h3>\n<div class=\"formula-box searchable\">Pediatric Dose = [Age (years) / (Age (years) + 12)] \u00d7 Adult Dose</div>\n<div class=\"source-line\">Source: classical age-based pediatric dosing rule. Remington: The Science and Practice of Pharmacy, \"Pediatric Dosage Forms\" chapter. Considered historical/approximate; not used for precise modern dosing.</div>\n<h3>b. Clark's Rule</h3>\n<div class=\"formula-box searchable\">Pediatric Dose = [Weight (kg) / 70] \u00d7 Adult Dose</div>\n<div class=\"source-line\">Source: classical weight-based pediatric dosing rule. Remington: The Science and Practice of Pharmacy. Considered historical/approximate; not used for precise modern dosing.</div>\n<h3>c. Geriatric Considerations</h3>\n<div class=\"where\">\n<div>\u2022 Start low, go slow.</div>\n<div>\u2022 Consider reduced renal &amp; hepatic function.</div>\n<div>\u2022 Monitor for adverse effects.</div>\n<div>\u2022 Adjust dose based on individual response and comorbidities.</div>\n</div>\n<div class=\"source-line\">Source: general geriatric prescribing principles. American Geriatrics Society Beers Criteria\u00ae for Potentially Inappropriate Medication Use in Older Adults.</div>\n</section>\n<section class=\"group\" id=\"misc\">\n<h2>8. Miscellaneous Calculations</h2>\n<h3>a. Specific Gravity</h3>\n<div class=\"formula-box searchable\">Specific Gravity = Weight of Substance / Weight of Equal Volume of Water</div>\n<h3>b. Percentage Error</h3>\n<div class=\"formula-box searchable\">Percentage Error (%) = |Experimental Value \u2212 Accepted Value| / Accepted Value \u00d7 100</div>\n<div class=\"source-line\">Source: standard analytical chemistry definitions. Used across USP General Chapter &lt;1010&gt; Analytical Data and general pharmaceutical analysis texts.</div>\n</section>\n</div>","interactions":"<div>\n<nav class=\"section-nav\">\n<strong>Jump to section</strong>\n<a href=\"#int-mechanisms\">Mechanism Overview</a>\n<a href=\"#int-common\">Most Common Interactions</a>\n<a href=\"#int-practical\">Most Practical (Everyday) Interactions</a>\n<a href=\"#int-advanced\">More Advanced / Specialist Interactions</a>\n<a href=\"#int-cyp\">CYP450 &amp; Metabolic Interactions</a>\n<a href=\"#int-absorption\">Absorption / Chelation Interactions</a>\n<a href=\"#int-electrolyte\">Electrolyte &amp; Renal-Risk Combinations</a>\n<a href=\"#int-serotonin-qt\">Serotonin Syndrome &amp; QT Prolongation</a>\n<a href=\"#int-food\">Food\u2013Drug Interactions</a>\n<a href=\"#int-sources\">Foundational Sources</a>\n</nav>\n<div class=\"disclaimer\" style=\"margin-bottom:1.5rem;\">\n    \u26a0\ufe0f This list covers well-established, extensively documented interactions used as teaching\n    examples in pharmacy curricula. It is <strong>not exhaustive</strong> and is not a\n    substitute for a full interaction-checking service (Lexicomp, Micromedex, Stockley's) or\n    the patient's complete medication list. Always run a full check before dispensing or\n    counseling.\n  </div>\n<section class=\"group\" id=\"int-mechanisms\">\n<h2>Mechanism Overview</h2>\n<div class=\"where\">\n<div><strong>Pharmacokinetic interactions</strong>. One drug changes the absorption, distribution, metabolism, or excretion of another (e.g., CYP450 inhibition/induction, chelation, protein-binding displacement, altered renal clearance).</div>\n<div><strong>Pharmacodynamic interactions</strong>. Two drugs act on the same or opposing physiological pathway, producing additive, synergistic, or antagonistic effects (e.g., two QT-prolonging drugs, two serotonergic drugs, two drugs raising potassium).</div>\n</div>\n<div class=\"source-line\">Source: Hansten PD, Horn JR. \"Hansten and Horn's Drug Interactions Analysis and Management.\" Wolters Kluwer.</div>\n</section>\n<section class=\"group\" id=\"int-common\">\n<h2>Most Common Interactions</h2>\n<div class=\"category-intro\">\n      The interactions you'll see constantly in community/retail pharmacy. Most patients on\n      chronic therapy will eventually present with one of these combinations.\n    </div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Warfarin + NSAIDs (ibuprofen, naproxen, diclofenac)</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> NSAIDs inhibit platelet aggregation and damage the gastric mucosa on their own; combined with warfarin's anticoagulant effect, bleeding risk is additive. Some NSAIDs also displace warfarin from plasma protein binding, transiently raising free warfarin levels.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Significantly increased risk of GI bleeding and elevated INR.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Avoid the combination when possible; recommend acetaminophen for pain instead. If NSAID use is unavoidable, use the lowest dose for the shortest duration and monitor INR more frequently.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for warfarin (DailyMed); Hansten &amp; Horn's Drug Interactions Analysis and Management.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Warfarin + Macrolides / Metronidazole / TMP-SMX / Fluconazole</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> These antibiotics/antifungals inhibit CYP2C9 (the main enzyme that clears warfarin) or CYP3A4, slowing warfarin metabolism and letting it accumulate.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> INR can rise sharply within days, increasing bleeding risk.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Check INR 3\u20135 days after starting or stopping the interacting antibiotic; consider empiric warfarin dose reduction for high-risk combinations (e.g., fluconazole).</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for warfarin (DailyMed); Stockley's Drug Interactions, Pharmaceutical Press.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">ACE Inhibitors / ARBs + Potassium-sparing diuretics or K\u207a supplements</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> ACEi/ARBs already reduce aldosterone-driven potassium excretion; adding spironolactone, amiloride, or oral potassium compounds the effect.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Hyperkalemia, which can cause dangerous cardiac arrhythmias.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Monitor serum potassium and renal function periodically, especially in CKD, diabetes, or elderly patients; counsel on avoiding potassium-rich salt substitutes.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for ACE inhibitors/ARBs (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Statins + Strong CYP3A4 inhibitors (clarithromycin, itraconazole, grapefruit juice)</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Simvastatin and atorvastatin are metabolized by CYP3A4; inhibiting this enzyme causes statin blood levels to climb well above normal.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Increased risk of myopathy and, rarely, life-threatening rhabdomyolysis.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Temporarily hold the statin during a short antibiotic course, or switch to a statin with minimal CYP3A4 dependence (rosuvastatin, pravastatin) for chronic interacting therapy.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for simvastatin/atorvastatin (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Tetracyclines / Fluoroquinolones + Dairy, Calcium, Iron, Antacids</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Divalent/trivalent cations (Ca\u00b2\u207a, Mg\u00b2\u207a, Al\u00b3\u207a, Fe\u00b2\u207a/Fe\u00b3\u207a) chelate these antibiotics in the gut, forming an insoluble complex that can't be absorbed.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Markedly reduced antibiotic blood levels. Risk of treatment failure.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Separate dosing by at least 2 hours before or 4\u20136 hours after the interacting product; counsel patients specifically about dairy, multivitamins, and antacids.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for tetracyclines/fluoroquinolones (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Levothyroxine + Calcium/Iron supplements, PPIs, Coffee</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Calcium and iron chelate levothyroxine in the gut; PPIs raise gastric pH, reducing tablet dissolution; coffee reduces absorption through an unclear mechanism.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Under-replacement. Rising TSH despite \"adequate\" dosing.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Take levothyroxine on an empty stomach, 30\u201360 minutes before food/coffee, and separate from calcium/iron by at least 4 hours.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for levothyroxine (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Digoxin + Loop or Thiazide diuretics</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> These diuretics cause potassium (and magnesium) loss; digoxin's toxicity threshold drops sharply when potassium is low, because digoxin and K\u207a compete for the same binding site on Na\u207a/K\u207a-ATPase.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Digoxin toxicity (nausea, visual disturbances, arrhythmias) even at \"normal\" digoxin levels.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Monitor serum potassium and digoxin level together, particularly after diuretic dose changes.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for digoxin (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Metronidazole / Tinidazole + Alcohol</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> These drugs inhibit aldehyde dehydrogenase, the enzyme that clears acetaldehyde, alcohol's toxic metabolite. The same mechanism as disulfiram.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Flushing, throbbing headache, nausea, vomiting, tachycardia (disulfiram-like reaction).</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Counsel patients to avoid alcohol during treatment and for 48\u201372 hours after the last dose.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for metronidazole (DailyMed).</div>\n</div>\n</section>\n<section class=\"group\" id=\"int-practical\">\n<h2>Most Practical (Everyday Counseling) Interactions</h2>\n<div class=\"category-intro\">\n      These are less about rare toxicity and more about the calls a pharmacist actually gets:\n      \"can I take this OTC med with my prescription,\" therapeutic duplication, and things that\n      quietly reduce efficacy rather than causing a dramatic event.\n    </div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">NSAIDs + Antihypertensives (ACEi, ARBs, diuretics, beta-blockers)</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> NSAIDs inhibit renal prostaglandin synthesis, which normally helps maintain renal blood flow and sodium excretion; blocking this promotes sodium/fluid retention and vasoconstriction.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Reduced antihypertensive efficacy and, in vulnerable patients, worsened blood pressure control or renal function.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Recommend acetaminophen or short-term topical NSAIDs instead; if oral NSAID is truly needed, use the lowest effective dose for the shortest time and monitor blood pressure.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for NSAIDs (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Benzodiazepines + Opioids</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Both classes depress the central nervous system and respiratory drive through different but additive mechanisms (GABA potentiation vs. mu-opioid receptor activation).</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Profound sedation, respiratory depression, and death. This combination carries an FDA boxed warning.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Avoid co-prescribing when possible; if unavoidable, use the lowest effective doses, counsel the patient/caregiver on overdose signs, and consider naloxone co-prescribing.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-contra\">Boxed warning</span></div>\n<div class=\"source-line\">Source: FDA Drug Safety Communication (2016) on combined use of opioids and benzodiazepines/CNS depressants.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">SSRIs + NSAIDs or Aspirin</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> SSRIs deplete platelet serotonin, impairing platelet aggregation; combined with an NSAID's gastric mucosal effect and antiplatelet action, bleeding risk compounds.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Increased risk of GI bleeding, particularly in elderly patients.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Consider a PPI for gastroprotection if the combination is necessary; recommend acetaminophen as an alternative when feasible.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for SSRIs (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Beta-blockers + Insulin/Sulfonylureas</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Beta-blockers (especially non-selective ones) blunt the adrenergic warning signs of hypoglycemia. Tremor, palpitations, tachycardia. Without necessarily preventing the hypoglycemia itself.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> \"Masked\" hypoglycemia. The patient may not recognize a low blood sugar episode until it's severe.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Counsel patients to monitor blood glucose more closely and recognize sweating as a residual warning sign; prefer a cardioselective beta-blocker if one is needed.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for beta-blockers (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Antacids/Dairy + Oral Fluoroquinolones (practical counseling case)</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Same chelation mechanism as above. This is the single most common \"can I take my antibiotic with milk/Tums\" counseling question in retail practice.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Subtherapeutic antibiotic levels and possible treatment failure.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Always ask about antacid/calcium/multivitamin use when dispensing a fluoroquinolone; give explicit timing instructions at counseling.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for fluoroquinolones (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Pseudoephedrine (OTC decongestant) + MAOIs or uncontrolled hypertension</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Pseudoephedrine is a sympathomimetic; MAOIs prevent breakdown of catecholamines, so combined sympathetic stimulation can spike dramatically.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Hypertensive crisis.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Always screen OTC cold/flu purchases against MAOI use and poorly controlled hypertension; recommend a nasal saline or non-sympathomimetic alternative instead.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for pseudoephedrine-containing products (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Proton Pump Inhibitors + Methotrexate</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> PPIs are thought to compete with methotrexate for renal tubular transporters, delaying its elimination.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Elevated methotrexate levels and increased toxicity risk, most relevant at high (oncologic) doses; less clear at low weekly RA/psoriasis doses but still noted on labeling.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Use caution or consider a temporary PPI hold around high-dose methotrexate administration; monitor for toxicity signs (mucositis, cytopenias) with chronic low-dose combinations.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-moderate\">Moderate</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for methotrexate (DailyMed).</div>\n</div>\n</section>\n<section class=\"group\" id=\"int-advanced\">\n<h2>More Advanced / Specialist-Level Interactions</h2>\n<div class=\"category-intro\">\n      Higher-acuity combinations typically managed in hospital, oncology, transplant, or\n      psychiatric specialty settings. Good to recognize even if you won't manage them solo\n      early in practice.\n    </div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">MAOIs + SSRIs/SNRIs, Meperidine, Tramadol, Triptans</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> All of these agents raise synaptic serotonin through different mechanisms (reuptake inhibition, opioid-receptor-linked serotonin release); MAOIs already prevent serotonin breakdown, so combining floods the synapse.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Serotonin syndrome. Agitation, hyperthermia, clonus, autonomic instability; can be fatal.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Require a minimum 2-week washout between an MAOI and a serotonergic drug (5 weeks after stopping fluoxetine specifically, due to its long half-life).</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-contra\">Contraindicated</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for MAOIs (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">High-dose Methotrexate + NSAIDs / Trimethoprim</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> NSAIDs reduce renal methotrexate clearance via prostaglandin-mediated renal blood flow changes; trimethoprim adds a separate antifolate effect on top of methotrexate's own antifolate action.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Severe bone marrow suppression, mucositis, hepatotoxicity.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Avoid combination around high-dose oncologic methotrexate; use extreme caution even with low-dose weekly methotrexate for rheumatologic conditions.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for methotrexate (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Lithium + NSAIDs / Thiazides / ACE inhibitors</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Lithium is renally cleared almost entirely unchanged; NSAIDs reduce renal blood flow, thiazides increase proximal tubular lithium reabsorption, and ACE inhibitors reduce glomerular filtration. All reduce lithium clearance.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Lithium toxicity. Tremor, ataxia, confusion, seizures, arrhythmias. Has a narrow therapeutic index, so even modest clearance changes matter.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Avoid if possible; if combination is clinically necessary, check lithium levels more frequently after starting/stopping the interacting drug.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for lithium (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Amiodarone + Digoxin / Warfarin / Statins (multi-pathway interaction)</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Amiodarone inhibits P-glycoprotein (raising digoxin levels), CYP2C9 (raising warfarin levels), and CYP3A4 (raising statin levels) simultaneously. A single drug causing three separate clinically important interactions.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Digoxin toxicity, supratherapeutic INR/bleeding, and statin-induced myopathy can each occur independently in the same patient.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> When starting amiodarone, proactively reduce digoxin and warfarin doses (commonly by ~30\u201350%) and switch to a non-CYP3A4-dependent statin; monitor levels closely.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for amiodarone (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">\"Triple Whammy\": ACEi/ARB + Diuretic + NSAID</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Each drug independently reduces renal perfusion or filtration through a different mechanism (efferent arteriolar dilation, volume depletion, afferent arteriolar constriction via prostaglandin inhibition); together they can abruptly drop glomerular filtration.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Acute kidney injury, sometimes requiring hospitalization, plus hyperkalemia.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Avoid the three-way combination, especially in dehydration, elderly patients, or pre-existing renal impairment; counsel patients on this combination specifically since NSAIDs are often taken OTC without informing the prescriber.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: Loboz KK, Shenfield GM. \"Drug combinations and impaired renal function \u2013 the 'triple whammy'.\" Br J Clin Pharmacol. 2005;59(2):239\u2013243.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Azole antifungals (voriconazole, itraconazole) + Tacrolimus/Cyclosporine</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Azoles are potent CYP3A4 inhibitors; calcineurin inhibitors (tacrolimus, cyclosporine) are almost entirely CYP3A4-metabolized and have a narrow therapeutic index.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Calcineurin inhibitor levels can rise several-fold, risking nephrotoxicity and neurotoxicity.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Empiric transplant-protocol dose reduction of the calcineurin inhibitor (often by 50% or more) when starting an azole, with close level monitoring. This is typically managed by a transplant pharmacist/team.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for tacrolimus/cyclosporine (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Enzyme inducers (rifampin, carbamazepine, phenytoin) + Oral contraceptives, Warfarin, Immunosuppressants</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> These agents strongly induce CYP3A4 (and other enzymes), accelerating metabolism of many co-administered drugs over 1\u20133 weeks as enzyme induction builds.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Contraceptive failure, subtherapeutic anticoagulation, or transplant rejection from subtherapeutic immunosuppressant levels.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Counsel on backup contraception; monitor INR closely when starting/stopping the inducer; involve a transplant specialist for immunosuppressant dose adjustment.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for rifampin/carbamazepine/phenytoin (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Linezolid + Serotonergic drugs or Tyramine-rich foods</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Linezolid is a reversible, nonselective MAO inhibitor. A property often overlooked because it's primarily used as an antibiotic.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Serotonin syndrome with serotonergic drugs; hypertensive crisis with large tyramine intake.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Screen for antidepressant use before starting linezolid; advise avoiding large amounts of tyramine-rich foods during therapy.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for linezolid (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Clozapine + CYP1A2 inhibitors/inducers (e.g., smoking cessation)</div>\n<div class=\"field\"><span class=\"field-label\">Why it happens:</span> Clozapine is primarily cleared by CYP1A2; tobacco smoke (via polycyclic aromatic hydrocarbons, not nicotine itself) induces CYP1A2, so patients who quit smoking abruptly lose that induction.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical consequence:</span> Clozapine levels can rise substantially within days of quitting smoking, increasing seizure and sedation risk.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Monitor clozapine levels and consider empiric dose reduction whenever a patient stops or drastically reduces smoking; same concern in reverse if they resume smoking.</div>\n<div class=\"field\"><span class=\"field-label\">Severity:</span> <span class=\"sev sev-major\">Major</span></div>\n<div class=\"source-line\">Source: FDA prescribing information for clozapine (DailyMed).</div>\n</div>\n</section>\n<section class=\"group\" id=\"int-cyp\">\n<h2>CYP450 &amp; Metabolic Interactions</h2>\n<table class=\"int-table searchable\">\n<thead><tr><th>Enzyme</th><th>Common inhibitors</th><th>Common inducers</th><th>Example affected substrates</th></tr></thead>\n<tbody>\n<tr>\n<td class=\"pair\">CYP3A4</td>\n<td>Clarithromycin, itraconazole, ketoconazole, ritonavir, grapefruit juice</td>\n<td>Rifampin, carbamazepine, phenytoin, St. John's Wort</td>\n<td>Statins, midazolam, cyclosporine, many antiretrovirals, warfarin (partial)</td>\n</tr>\n<tr>\n<td class=\"pair\">CYP2D6</td>\n<td>Fluoxetine, paroxetine, bupropion, quinidine</td>\n<td>(few clinically significant inducers)</td>\n<td>Codeine (reduced conversion to morphine), tamoxifen, many antipsychotics/antidepressants</td>\n</tr>\n<tr>\n<td class=\"pair\">CYP2C9</td>\n<td>Fluconazole, amiodarone, metronidazole</td>\n<td>Rifampin</td>\n<td>Warfarin, phenytoin</td>\n</tr>\n<tr>\n<td class=\"pair\">CYP2C19</td>\n<td>Omeprazole, esomeprazole, fluvoxamine</td>\n<td>Rifampin</td>\n<td>Clopidogrel (activation impaired), phenytoin</td>\n</tr>\n<tr>\n<td class=\"pair\">CYP1A2</td>\n<td>Ciprofloxacin, fluvoxamine</td>\n<td>Smoking (tobacco), rifampin</td>\n<td>Theophylline, clozapine, caffeine</td>\n</tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: FDA Table of Substrates, Inhibitors and Inducers (Drug Development and Drug Interactions resource, fda.gov); Flockhart DA, \"Drug Interactions: Cytochrome P450 Drug Interaction Table,\" Indiana University School of Medicine.</div>\n</section>\n<section class=\"group\" id=\"int-absorption\">\n<h2>Absorption / Chelation Interactions</h2>\n<table class=\"int-table searchable\">\n<thead><tr><th>Combination</th><th>Effect</th><th>Practical management</th></tr></thead>\n<tbody>\n<tr>\n<td class=\"pair\">Tetracyclines / Fluoroquinolones + Calcium, Iron, Magnesium, Aluminum, Zinc, Dairy</td>\n<td>Chelation forms insoluble complex \u2192 markedly reduced antibiotic absorption</td>\n<td>Separate by \u22652 hours before or 4\u20136 hours after the cation-containing product</td>\n</tr>\n<tr>\n<td class=\"pair\">Levothyroxine + Calcium/Iron supplements, PPIs, coffee</td>\n<td>Reduced levothyroxine absorption</td>\n<td>Take levothyroxine on an empty stomach; separate from interacting agents by \u22654 hours</td>\n</tr>\n<tr>\n<td class=\"pair\">Bisphosphonates + Calcium, antacids, food</td>\n<td>Markedly reduced bisphosphonate absorption</td>\n<td>Take on empty stomach with plain water only; wait 30\u201360 minutes before other intake</td>\n</tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: respective FDA-approved prescribing information (DailyMed); Remington: The Science and Practice of Pharmacy.</div>\n</section>\n<section class=\"group\" id=\"int-electrolyte\">\n<h2>Electrolyte &amp; Renal-Risk Combinations</h2>\n<table class=\"int-table searchable\">\n<thead><tr><th>Combination</th><th>Risk</th><th>Practical management</th></tr></thead>\n<tbody>\n<tr>\n<td class=\"pair\">ACEi/ARB + Spironolactone/Eplerenone + NSAID (\"triple whammy\")</td>\n<td>Acute kidney injury and hyperkalemia. Well-documented \"triple whammy\" combination</td>\n<td>Avoid triple combination; if unavoidable, monitor renal function and potassium closely</td>\n</tr>\n<tr>\n<td class=\"pair\">NSAIDs + Diuretics + ACEi/ARB</td>\n<td>Same \"triple whammy\" mechanism. NSAID reduces renal prostaglandin-mediated perfusion</td>\n<td>Counsel patients to avoid OTC NSAIDs if on this combination</td>\n</tr>\n<tr>\n<td class=\"pair\">Trimethoprim-sulfamethoxazole + ACEi/ARB/Spironolactone</td>\n<td>Trimethoprim acts like a potassium-sparing diuretic \u2192 hyperkalemia, particularly in elderly/CKD</td>\n<td>Monitor potassium, especially in renal impairment</td>\n</tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: \"Triple whammy\" nomenclature and risk described in: Loboz KK, Shenfield GM. \"Drug combinations and impaired renal function \u2013 the 'triple whammy'.\" Br J Clin Pharmacol. 2005;59(2):239\u2013243.</div>\n</section>\n<section class=\"group\" id=\"int-serotonin-qt\">\n<h2>Serotonin Syndrome &amp; QT Prolongation</h2>\n<table class=\"int-table searchable\">\n<thead><tr><th>Combination</th><th>Risk</th><th>Practical management</th></tr></thead>\n<tbody>\n<tr>\n<td class=\"pair\">SSRIs/SNRIs + Tramadol, Linezolid, Triptans, St. John's Wort</td>\n<td>Serotonin syndrome (agitation, hyperthermia, clonus, autonomic instability)</td>\n<td>Avoid combination where possible; educate patient on early symptoms</td>\n</tr>\n<tr>\n<td class=\"pair\">Methylene blue + Serotonergic drugs</td>\n<td>Serotonin syndrome. Methylene blue is a potent MAO-A inhibitor</td>\n<td>Discontinue serotonergic drug ~2 weeks before methylene blue if elective; FDA drug safety communication applies</td>\n</tr>\n<tr>\n<td class=\"pair\">Two or more QT-prolonging drugs (e.g., macrolides, fluoroquinolones, antipsychotics, ondansetron, methadone)</td>\n<td>Additive QT prolongation \u2192 torsades de pointes risk</td>\n<td>Check baseline ECG/QTc when combining agents; correct hypokalemia/hypomagnesemia</td>\n</tr>\n</tbody>\n</table>\n<div class=\"source-line\">Sources: FDA Drug Safety Communications (fda.gov/drugsafety); CredibleMeds\u00ae QTdrugs list (crediblemeds.org), maintained by AZCERT. A widely used clinical reference for QT-prolonging drugs.</div>\n</section>\n<section class=\"group\" id=\"int-food\">\n<h2>Food\u2013Drug Interactions</h2>\n<table class=\"int-table searchable\">\n<thead><tr><th>Food / Substance</th><th>Interacts with</th><th>Effect</th></tr></thead>\n<tbody>\n<tr>\n<td class=\"pair\">Grapefruit juice</td>\n<td>Statins (simvastatin, atorvastatin), some calcium channel blockers, cyclosporine</td>\n<td>Inhibits intestinal CYP3A4 \u2192 increased drug levels and toxicity risk</td>\n</tr>\n<tr>\n<td class=\"pair\">Vitamin K\u2013rich leafy greens</td>\n<td>Warfarin</td>\n<td>Antagonizes anticoagulant effect. Advise consistent (not zero) intake, not avoidance</td>\n</tr>\n<tr>\n<td class=\"pair\">Tyramine-rich foods (aged cheese, cured meats, fermented products)</td>\n<td>MAOIs</td>\n<td>Hypertensive crisis</td>\n</tr>\n<tr>\n<td class=\"pair\">Alcohol</td>\n<td>Metronidazole, Tinidazole</td>\n<td>Disulfiram-like reaction (flushing, nausea, tachycardia)</td>\n</tr>\n<tr>\n<td class=\"pair\">Dairy products</td>\n<td>Tetracyclines, fluoroquinolones</td>\n<td>Calcium chelation \u2192 reduced antibiotic absorption</td>\n</tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: FDA-approved prescribing information for each agent (DailyMed); Remington: The Science and Practice of Pharmacy.</div>\n</section>\n<section class=\"group\" id=\"int-sources\">\n<h2>Foundational Sources for Interaction Checking</h2>\n<div class=\"where\">\n<div><strong>Stockley's Drug Interactions</strong>. Pharmaceutical Press. The classic pharmacist reference text for interaction mechanism and severity.</div>\n<div><strong>Hansten &amp; Horn's Drug Interactions Analysis and Management</strong>. Wolters Kluwer.</div>\n<div><strong>Lexicomp / UpToDate Interactions, Micromedex</strong>. Subscription clinical decision-support databases used in hospital/community pharmacy practice.</div>\n<div><strong>FDA prescribing information (via DailyMed, dailymed.nlm.nih.gov)</strong>. Official, free, drug-label-level interaction warnings for US-approved products.</div>\n<div><strong>CredibleMeds\u00ae (crediblemeds.org)</strong>. Maintained by AZCERT, a widely used free reference specifically for QT-prolonging drugs.</div>\n<div><strong>FDA Drug Interactions Table (fda.gov)</strong>. CYP450 substrate/inhibitor/inducer reference used in drug development.</div>\n</div>\n<div class=\"tip\">\n      For real dispensing/counseling decisions, run the patient's actual medication list through\n      a licensed interaction-checking database (Lexicomp, Micromedex) rather than relying on a\n      static list like this one. This page is for learning the classic, most-tested patterns.\n    </div>\n</section>\n</div>","pregnancy":"<div>\n<nav class=\"section-nav\">\n<strong>Jump to section</strong>\n<a href=\"#preg-system\">Old vs. Current Labeling System</a>\n<a href=\"#preg-avoid\">Well-Documented Teratogens to Avoid</a>\n<a href=\"#preg-safer\">Generally Preferred Options in Pregnancy</a>\n<a href=\"#lact-safe\">Generally Compatible with Breastfeeding</a>\n<a href=\"#lact-avoid\">Avoid or Use With Caution in Lactation</a>\n</nav>\n<section class=\"group\" id=\"preg-system\">\n<h2>Old vs. Current Labeling System</h2>\n<div class=\"where\">\n<div><strong>Old FDA Pregnancy Categories (A/B/C/D/X)</strong>. Used on US labels until 2015. A = controlled studies show no risk; B = animal studies show no risk, no adequate human studies; C = risk cannot be ruled out; D = evidence of human risk, but benefit may outweigh it; X = contraindicated, risk clearly outweighs any benefit. Still seen in older references and many countries' labeling.</div>\n<div><strong>Current system. Pregnancy and Lactation Labeling Rule (PLLR)</strong>. Replaced the letter categories on US labels with narrative subsections: \"Pregnancy,\" \"Lactation,\" and \"Females and Males of Reproductive Potential,\" describing actual risk data, dosing considerations, and a pregnancy exposure registry if one exists.</div>\n</div>\n<div class=\"source-line\">Source: FDA Pregnancy and Lactation Labeling Rule (PLLR), Federal Register, effective June 30, 2015 (fda.gov).</div>\n</section>\n<section class=\"group\" id=\"preg-avoid\">\n<h2>Well-Documented Teratogens / High-Risk Agents to Avoid</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">ACE inhibitors / ARBs</div>\n<div class=\"field\"><span class=\"field-label\">Risk:</span> Fetal renal damage, oligohydramnios, skull hypoplasia. Especially 2nd/3rd trimester exposure.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Switch to a pregnancy-safe antihypertensive (e.g., labetalol, nifedipine, methyldopa) before or immediately upon confirming pregnancy.</div>\n<div class=\"source-line\">Source: FDA prescribing information for ACE inhibitors/ARBs (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Warfarin</div>\n<div class=\"field\"><span class=\"field-label\">Risk:</span> \"Fetal warfarin syndrome\" (nasal hypoplasia, skeletal abnormalities) with 1st trimester exposure; CNS/bleeding risk later.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Switch to low molecular weight heparin for anticoagulation during pregnancy where possible.</div>\n<div class=\"source-line\">Source: FDA prescribing information for warfarin (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Isotretinoin</div>\n<div class=\"field\"><span class=\"field-label\">Risk:</span> Severe, well-documented birth defects (craniofacial, cardiac, CNS). One of the most teratogenic drugs on the market.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Requires enrollment in a pregnancy-prevention risk management program (e.g., iPLEDGE in the US) with mandatory contraception and pregnancy testing.</div>\n<div class=\"source-line\">Source: FDA prescribing information for isotretinoin (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Valproate / Valproic acid</div>\n<div class=\"field\"><span class=\"field-label\">Risk:</span> Neural tube defects, and long-term neurodevelopmental effects (reduced IQ) with in-utero exposure.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Avoid in pregnancy for migraine/general use; only used for epilepsy/bipolar disorder when no safer alternative controls the condition, with folic acid supplementation.</div>\n<div class=\"source-line\">Source: FDA prescribing information for valproate products (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">NSAIDs (3rd trimester)</div>\n<div class=\"field\"><span class=\"field-label\">Risk:</span> Premature closure of the fetal ductus arteriosus; oligohydramnios with prolonged use after ~20 weeks.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Avoid routine NSAID use starting around 20 weeks gestation; use acetaminophen instead when possible.</div>\n<div class=\"source-line\">Source: FDA Drug Safety Communication on NSAID use around 20 weeks or later in pregnancy (2020).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Methotrexate</div>\n<div class=\"field\"><span class=\"field-label\">Risk:</span> Potent teratogen and abortifacient; also used clinically to terminate ectopic pregnancy.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Contraindicated in pregnancy for all other indications; effective contraception required during and after therapy per labeling.</div>\n<div class=\"source-line\">Source: FDA prescribing information for methotrexate (DailyMed).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Statins</div>\n<div class=\"field\"><span class=\"field-label\">Risk:</span> Historically contraindicated due to theoretical concern about cholesterol's role in fetal development; recent FDA review softened this stance but caution remains standard practice.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Discontinue if pregnancy occurs or is planned, per current labeling and prescriber judgment.</div>\n<div class=\"source-line\">Source: FDA Drug Safety Communication (2021) revising statin pregnancy contraindication language.</div>\n</div>\n</section>\n<section class=\"group\" id=\"preg-safer\">\n<h2>Generally Preferred Options in Pregnancy (examples)</h2>\n<div class=\"where\">\n<div><strong>Antihypertensives:</strong> labetalol, methyldopa, nifedipine (extended release)</div>\n<div><strong>Analgesia:</strong> acetaminophen (paracetamol) is generally preferred over NSAIDs</div>\n<div><strong>Anticoagulation:</strong> low molecular weight heparin (does not cross the placenta)</div>\n<div><strong>Antiemetics (hyperemesis):</strong> pyridoxine \u00b1 doxylamine as first-line; ondansetron used with some ongoing safety discussion</div>\n<div><strong>Antibiotics generally considered lower-risk:</strong> penicillins, cephalosporins, azithromycin (class-dependent; always confirm current labeling for the specific agent and trimester)</div>\n</div>\n<div class=\"tip\">This is a starting orientation, not a prescribing decision. Obstetric drug selection should always be confirmed against current guidelines (e.g., ACOG) and the specific patient's trimester and comorbidities.</div>\n</section>\n<section class=\"group\" id=\"lact-safe\">\n<h2>Generally Compatible with Breastfeeding (examples)</h2>\n<div class=\"where\">\n<div>Acetaminophen, ibuprofen</div>\n<div>Most penicillins and cephalosporins</div>\n<div>Insulin (does not transfer meaningfully into milk)</div>\n<div>Levothyroxine</div>\n<div>Most inhaled asthma medications</div>\n</div>\n<div class=\"source-line\">Source: LactMed\u00ae database, National Library of Medicine (ncbi.nlm.nih.gov/books/NBK501922/). The standard free, continuously updated clinical reference for lactation safety.</div>\n</section>\n<section class=\"group\" id=\"lact-avoid\">\n<h2>Avoid or Use With Caution in Lactation (examples)</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Amiodarone</div>\n<div class=\"field\"><span class=\"field-label\">Concern:</span> High lipophilicity and long half-life lead to significant transfer into breast milk, with infant thyroid function risk from its iodine content.</div>\n<div class=\"source-line\">Source: LactMed\u00ae, National Library of Medicine.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Chemotherapy agents</div>\n<div class=\"field\"><span class=\"field-label\">Concern:</span> Cytotoxic to rapidly dividing infant cells; breastfeeding is generally contraindicated during active chemotherapy.</div>\n<div class=\"source-line\">Source: LactMed\u00ae, National Library of Medicine.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Codeine (maternal use)</div>\n<div class=\"field\"><span class=\"field-label\">Concern:</span> Ultra-rapid CYP2D6 metabolizer mothers can convert codeine to unusually high morphine levels, causing infant respiratory depression. Documented infant deaths led to an FDA boxed warning against codeine/tramadol in breastfeeding.</div>\n<div class=\"source-line\">Source: FDA Drug Safety Communication (2017). Codeine and tramadol contraindicated in breastfeeding mothers.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Lithium</div>\n<div class=\"field\"><span class=\"field-label\">Concern:</span> Transfers into breast milk in clinically relevant amounts; requires infant lithium level monitoring if breastfeeding is continued.</div>\n<div class=\"source-line\">Source: LactMed\u00ae, National Library of Medicine.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Radioactive iodine (\u00b9\u00b3\u00b9I)</div>\n<div class=\"field\"><span class=\"field-label\">Concern:</span> Concentrates in breast tissue and milk; breastfeeding must be discontinued, typically permanently for that lactation cycle.</div>\n<div class=\"source-line\">Source: LactMed\u00ae, National Library of Medicine.</div>\n</div>\n</section>\n</div>","highalert":"<div>\n<div class=\"disclaimer\" style=\"margin-bottom:1.5rem;\">\n    High-alert medications are drugs that bear a heightened risk of causing significant patient\n    harm when used in error. The error rate isn't necessarily higher, but the consequences are\n    more severe. This list is adapted from ISMP's official published list.\n  </div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Insulin (all formulations)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Narrow therapeutic index; dosing errors (especially unit confusion, e.g., \"U\" misread as a zero) cause severe hypoglycemia.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Always write \"units\" in full, never abbreviate as \"U\"; use insulin-specific syringes only; independent double-check for concentrated formulations (U-500).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Opioids (IV and oral, all agents)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Respiratory depression risk, especially with dose escalation, opioid-naive patients, or concurrent CNS depressants.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Use standardized dosing protocols/PCA order sets; monitor sedation score alongside respiratory rate; have naloxone available.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Anticoagulants (heparin, warfarin, DOACs, LMWH)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Narrow safety margin between therapeutic and bleeding-risk doses; multiple drug/food/renal-function interactions.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Use weight-based nomograms for heparin; verify renal function before LMWH/DOAC dosing; confirm indication-specific target INR for warfarin.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Concentrated electrolytes (potassium chloride injection, hypertonic saline)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Undiluted IV potassium chloride is potentially fatal if given as a direct push. A well-documented cause of preventable inpatient deaths.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Store concentrated electrolytes separately from ready-to-use solutions; require pharmacy-prepared dilutions rather than floor-stock vials in most hospital policies.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Chemotherapy agents (parenteral and oral)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Extremely narrow therapeutic index, cumulative and irreversible toxicity, complex body-surface-area/renal-adjusted dosing.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Independent double-check of dose calculations, use of standardized order templates, and verification against actual BSA/renal function before every cycle.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Neuromuscular blocking agents (e.g., rocuronium, succinylcholine)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Causes complete paralysis including respiratory muscles; accidental administration to a non-intubated, non-ventilated patient is rapidly fatal.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Store separately from other injectables with distinct warning labels; restrict to areas with airway management capability.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Sedatives used for moderate/deep sedation (e.g., propofol, midazolam infusions)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Rapid onset of deep sedation/respiratory depression with a narrow margin before airway compromise.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Continuous monitoring (pulse oximetry/capnography) during administration; resuscitation equipment immediately available.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Methotrexate (oral, non-oncologic use)</div>\n<div class=\"field\"><span class=\"field-label\">Why high-alert:</span> Intended weekly dosing has repeatedly been mistakenly given daily in real-world medication errors, causing fatal toxicity.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Many pharmacy systems flag oral methotrexate prescriptions for mandatory \"weekly dosing\" confirmation before dispensing.</div>\n</div>\n<div class=\"source-line\">Source: Institute for Safe Medication Practices (ISMP), \"List of High-Alert Medications in Acute Care Settings\" (ismp.org). The official, freely published US reference for this classification.</div>\n</div>","antidotes":"<div>\n<div class=\"disclaimer\" style=\"margin-bottom:1.5rem;\">\n    Reference only. Actual antidote dosing, timing windows, and treatment protocols must come\n    from a poison control center, toxicology reference (e.g., Goldfrank's Toxicologic\n    Emergencies), or current institutional protocol. This table identifies the correct antidote\n    and mechanism, not administration doses.\n  </div>\n<table class=\"int-table searchable\">\n<thead><tr><th>Toxin / Overdose</th><th>Antidote</th><th>Mechanism / Note</th></tr></thead>\n<tbody>\n<tr><td class=\"pair\">Acetaminophen (paracetamol)</td><td>N-acetylcysteine (NAC)</td><td>Replenishes glutathione, which detoxifies the hepatotoxic metabolite NAPQI</td></tr>\n<tr><td class=\"pair\">Opioids</td><td>Naloxone</td><td>Competitive mu-opioid receptor antagonist; short half-life may require repeat dosing</td></tr>\n<tr><td class=\"pair\">Benzodiazepines</td><td>Flumazenil</td><td>GABA-A/benzodiazepine receptor antagonist; used cautiously. Can precipitate seizures in chronic users or mixed overdose</td></tr>\n<tr><td class=\"pair\">Warfarin (excess anticoagulation/bleeding)</td><td>Vitamin K1 (phytonadione) \u00b1 fresh frozen plasma or PCC</td><td>Restores vitamin K\u2013dependent clotting factor synthesis; PCC/FFP provide immediate factor replacement for active bleeding</td></tr>\n<tr><td class=\"pair\">Unfractionated heparin</td><td>Protamine sulfate</td><td>Binds and neutralizes heparin directly</td></tr>\n<tr><td class=\"pair\">Digoxin</td><td>Digoxin immune Fab (DigiFab)</td><td>Antibody fragments bind free digoxin, pulling it out of tissue and inactivating it</td></tr>\n<tr><td class=\"pair\">Iron</td><td>Deferoxamine</td><td>Chelates free iron for renal excretion</td></tr>\n<tr><td class=\"pair\">Methanol / Ethylene glycol</td><td>Fomepizole (or ethanol as alternative)</td><td>Inhibits alcohol dehydrogenase, blocking formation of toxic metabolites</td></tr>\n<tr><td class=\"pair\">Organophosphate / Nerve agent poisoning</td><td>Atropine + Pralidoxime</td><td>Atropine blocks excess muscarinic stimulation; pralidoxime reactivates inhibited acetylcholinesterase if given early</td></tr>\n<tr><td class=\"pair\">Beta-blocker overdose</td><td>Glucagon</td><td>Bypasses the blocked beta-receptor to increase cAMP directly, restoring cardiac contractility</td></tr>\n<tr><td class=\"pair\">Calcium channel blocker overdose</td><td>Calcium gluconate/chloride; high-dose insulin euglycemic therapy</td><td>Calcium overcomes blockade; high-dose insulin improves myocardial metabolism and contractility</td></tr>\n<tr><td class=\"pair\">Cyanide poisoning</td><td>Hydroxocobalamin (or sodium thiosulfate)</td><td>Hydroxocobalamin binds cyanide directly to form cyanocobalamin, excreted renally</td></tr>\n<tr><td class=\"pair\">Methotrexate toxicity</td><td>Leucovorin (folinic acid)</td><td>\"Rescues\" normal cells by bypassing methotrexate's block on folate metabolism</td></tr>\n<tr><td class=\"pair\">Isoniazid overdose (seizures)</td><td>Pyridoxine (Vitamin B6)</td><td>Replenishes pyridoxine depleted by isoniazid, restoring GABA synthesis</td></tr>\n<tr><td class=\"pair\">Tricyclic antidepressant overdose (cardiotoxicity)</td><td>Sodium bicarbonate</td><td>Increases extracellular sodium and alkalinizes serum, reversing sodium-channel blockade</td></tr>\n<tr><td class=\"pair\">Lead poisoning</td><td>EDTA, DMSA (succimer), or dimercaprol depending on severity</td><td>Chelates lead for renal/biliary excretion</td></tr>\n<tr><td class=\"pair\">Local anesthetic systemic toxicity (LAST)</td><td>Intravenous lipid emulsion (\"lipid rescue\")</td><td>Thought to act as a \"lipid sink,\" extracting the lipophilic anesthetic from tissue</td></tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: Nelson LS, et al. \"Goldfrank's Toxicologic Emergencies,\" McGraw-Hill; American College of Medical Toxicology (ACMT) position statements (acmt.net); FDA-approved prescribing information for each antidote (DailyMed).</div>\n</div>","renalhepatic":"<div>\n<div class=\"disclaimer\" style=\"margin-bottom:1.5rem;\">\n    This tab flags <strong>which drug classes commonly need adjustment</strong> and why. It deliberately does not give specific adjusted doses, since those depend on the exact\n    agent, indication, and degree of impairment. Look up the specific dose from an official\n    renal/hepatic dosing reference (e.g., the Renal Drug Handbook, KDIGO guidance, or the\n    product's own prescribing information) once a flag here tells you to check.\n  </div>\n<h2 id=\"renal-flags\">Renal Impairment. Drug Classes to Flag</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Drug / Class</th><th>Why it needs a renal check</th></tr></thead>\n<tbody>\n<tr><td>Aminoglycosides (gentamicin, amikacin)</td><td>Renally cleared and independently nephrotoxic. Accumulation compounds their own kidney injury risk</td></tr>\n<tr><td>Vancomycin</td><td>Almost entirely renally cleared with a narrow therapeutic window; requires trough/AUC-based monitoring</td></tr>\n<tr><td>Digoxin</td><td>Renally cleared with a narrow therapeutic index. Impaired clearance quickly raises toxicity risk</td></tr>\n<tr><td>Metformin</td><td>Risk of lactic acidosis accumulation; contraindicated at eGFR &lt;30, caution/dose review 30\u201345</td></tr>\n<tr><td>Gabapentin / Pregabalin</td><td>Renally eliminated unchanged. Accumulation causes sedation, confusion, especially in the elderly</td></tr>\n<tr><td>Low molecular weight heparin (enoxaparin)</td><td>Renally cleared. Accumulates and raises bleeding risk at low CrCl</td></tr>\n<tr><td>Direct oral anticoagulants (DOACs)</td><td>Variable renal dependence (dabigatran most renally dependent). Caution or avoidance needed in renal impairment</td></tr>\n<tr><td>Allopurinol</td><td>Active metabolite (oxypurinol) accumulates in renal impairment, raising hypersensitivity/toxicity risk</td></tr>\n<tr><td>Lithium</td><td>Almost entirely renally cleared with a narrow therapeutic index. Small clearance changes matter greatly</td></tr>\n<tr><td>NSAIDs</td><td>Reduce renal blood flow via prostaglandin inhibition. Can precipitate or worsen renal impairment itself</td></tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: KDIGO Clinical Practice Guidelines (kdigo.org); Ashley C, Dunleavy A (eds.), \"The Renal Drug Handbook,\" CRC Press.</div>\n<h2 id=\"hepatic-flags\" style=\"margin-top:1.75rem;\">Hepatic Impairment. Drug Classes to Flag</h2>\n<table class=\"lab-table searchable\">\n<thead><tr><th>Drug / Class</th><th>Why it needs a hepatic check</th></tr></thead>\n<tbody>\n<tr><td>Acetaminophen</td><td>Hepatotoxic in overdose; total daily dose ceiling should be reduced in chronic liver disease or heavy alcohol use</td></tr>\n<tr><td>Statins</td><td>Hepatically metabolized; generally avoided or used cautiously in active liver disease</td></tr>\n<tr><td>Opioids (morphine, oxycodone)</td><td>Reduced first-pass hepatic metabolism raises bioavailability and effect. Start lower, extend dosing intervals; avoid meperidine (toxic metabolite accumulation)</td></tr>\n<tr><td>Benzodiazepines</td><td>Prefer agents without hepatically-produced active metabolites (lorazepam, oxazepam, temazepam. The \"LOT\" drugs) in significant liver disease</td></tr>\n<tr><td>Warfarin</td><td>Liver disease reduces synthesis of clotting factors independently, increasing sensitivity to warfarin's effect. Often needs lower doses with closer INR monitoring</td></tr>\n<tr><td>Rifampin / Isoniazid</td><td>Both independently hepatotoxic. Require baseline and periodic LFT monitoring, more so in existing liver disease</td></tr>\n<tr><td>Methotrexate</td><td>Hepatotoxic with cumulative dosing. Generally avoided or used with heightened monitoring in liver disease</td></tr>\n<tr><td>Phenytoin</td><td>Highly protein-bound and hepatically metabolized. Hypoalbuminemia from liver disease alters free drug levels significantly</td></tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: Verbeeck RK. \"Pharmacokinetics and dosage adjustment in patients with hepatic dysfunction.\" Eur J Clin Pharmacol. 2008;64(12):1147\u20131161; FDA prescribing information for each agent (DailyMed).</div>\n</div>","suffixes":"<div>\n<nav class=\"section-nav\">\n<strong>Jump to section</strong>\n<a href=\"#suf-cardio\">Cardiovascular</a>\n<a href=\"#suf-antimicrobial\">Antimicrobial / Antiviral</a>\n<a href=\"#suf-cns\">CNS / Psychiatric</a>\n<a href=\"#suf-gi\">GI / Respiratory</a>\n<a href=\"#suf-endo\">Endocrine / Metabolic</a>\n<a href=\"#suf-onco\">Oncology / Immunology</a>\n</nav>\n<div class=\"tip\">\n    These are World Health Organization International Nonproprietary Name (INN) \"stems\". Officially recognized word fragments used when naming new drugs so that the class is\n    recognizable from the name itself. They are strong pattern-recognition tools, not\n    universal rules. Always confirm the actual drug class.\n  </div>\n<section class=\"group\" id=\"suf-cardio\">\n<h2>Cardiovascular</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Stem</th><th>Class</th><th>Examples</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">-olol</td><td>Beta-blocker</td><td>propranolol, atenolol, metoprolol</td></tr>\n<tr><td class=\"abbr\">-pril</td><td>ACE inhibitor</td><td>lisinopril, enalapril, ramipril</td></tr>\n<tr><td class=\"abbr\">-sartan</td><td>Angiotensin II receptor blocker (ARB)</td><td>losartan, valsartan, candesartan</td></tr>\n<tr><td class=\"abbr\">-dipine</td><td>Dihydropyridine calcium channel blocker</td><td>amlodipine, nifedipine, felodipine</td></tr>\n<tr><td class=\"abbr\">-statin</td><td>HMG-CoA reductase inhibitor (lipid-lowering)</td><td>atorvastatin, simvastatin, rosuvastatin</td></tr>\n<tr><td class=\"abbr\">-parin</td><td>Heparin / heparinoid anticoagulant</td><td>enoxaparin, dalteparin, tinzaparin</td></tr>\n<tr><td class=\"abbr\">-xaban</td><td>Factor Xa inhibitor (DOAC)</td><td>rivaroxaban, apixaban, edoxaban</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"suf-antimicrobial\">\n<h2>Antimicrobial / Antiviral</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Stem</th><th>Class</th><th>Examples</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">-cillin</td><td>Penicillin antibiotic</td><td>amoxicillin, ampicillin, piperacillin</td></tr>\n<tr><td class=\"abbr\">-floxacin</td><td>Fluoroquinolone antibiotic</td><td>ciprofloxacin, levofloxacin, moxifloxacin</td></tr>\n<tr><td class=\"abbr\">-cycline</td><td>Tetracycline antibiotic</td><td>doxycycline, minocycline, tetracycline</td></tr>\n<tr><td class=\"abbr\">-mycin / -micin</td><td>Macrolide (-mycin) or aminoglycoside (-micin) antibiotic. Spelling distinguishes the family</td><td>erythromycin, clarithromycin (macrolides); gentamicin, tobramycin (aminoglycosides)</td></tr>\n<tr><td class=\"abbr\">-azole</td><td>Antifungal (imidazole/triazole). Note: also used for PPIs, context distinguishes them</td><td>fluconazole, itraconazole, ketoconazole</td></tr>\n<tr><td class=\"abbr\">-fungin</td><td>Echinocandin antifungal</td><td>caspofungin, micafungin</td></tr>\n<tr><td class=\"abbr\">-vir</td><td>Antiviral</td><td>acyclovir, oseltamivir, ritonavir</td></tr>\n<tr><td class=\"abbr\">-navir</td><td>HIV protease inhibitor (subclass of -vir)</td><td>ritonavir, lopinavir, atazanavir</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"suf-cns\">\n<h2>CNS / Psychiatric</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Stem</th><th>Class</th><th>Examples</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">-azepam</td><td>Benzodiazepine</td><td>diazepam, lorazepam, alprazolam</td></tr>\n<tr><td class=\"abbr\">-barbital</td><td>Barbiturate</td><td>phenobarbital, pentobarbital</td></tr>\n<tr><td class=\"abbr\">-oxetine</td><td>Selective serotonin reuptake inhibitor (SSRI)</td><td>fluoxetine, paroxetine, atomoxetine (an SNRI, similar stem)</td></tr>\n<tr><td class=\"abbr\">-triptan</td><td>5-HT1 receptor agonist (migraine)</td><td>sumatriptan, rizatriptan, zolmitriptan</td></tr>\n<tr><td class=\"abbr\">-caine</td><td>Local anesthetic</td><td>lidocaine, bupivacaine, procaine</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"suf-gi\">\n<h2>GI / Respiratory</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Stem</th><th>Class</th><th>Examples</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">-prazole</td><td>Proton pump inhibitor (PPI)</td><td>omeprazole, pantoprazole, esomeprazole</td></tr>\n<tr><td class=\"abbr\">-tidine</td><td>H2-receptor antagonist</td><td>ranitidine, famotidine, cimetidine</td></tr>\n<tr><td class=\"abbr\">-terol</td><td>Beta-2 agonist bronchodilator</td><td>salbutamol/albuterol (note: exception to strict stem spelling), salmeterol, formoterol</td></tr>\n<tr><td class=\"abbr\">-tropium</td><td>Anticholinergic bronchodilator</td><td>ipratropium, tiotropium</td></tr>\n<tr><td class=\"abbr\">-setron</td><td>5-HT3 receptor antagonist (antiemetic)</td><td>ondansetron, granisetron</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"suf-endo\">\n<h2>Endocrine / Metabolic</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Stem</th><th>Class</th><th>Examples</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">-gliptin</td><td>DPP-4 inhibitor (antidiabetic)</td><td>sitagliptin, saxagliptin</td></tr>\n<tr><td class=\"abbr\">-gliflozin</td><td>SGLT2 inhibitor (antidiabetic)</td><td>empagliflozin, dapagliflozin</td></tr>\n<tr><td class=\"abbr\">-glitazone</td><td>Thiazolidinedione (antidiabetic)</td><td>pioglitazone, rosiglitazone</td></tr>\n<tr><td class=\"abbr\">-glutide</td><td>GLP-1 receptor agonist</td><td>semaglutide, liraglutide, dulaglutide</td></tr>\n</tbody>\n</table>\n</section>\n<section class=\"group\" id=\"suf-onco\">\n<h2>Oncology / Immunology</h2>\n<table class=\"term-table searchable\">\n<thead><tr><th>Stem</th><th>Class</th><th>Examples</th></tr></thead>\n<tbody>\n<tr><td class=\"abbr\">-mab</td><td>Monoclonal antibody</td><td>infliximab, trastuzumab, rituximab, adalimumab</td></tr>\n<tr><td class=\"abbr\">-nib</td><td>Small-molecule kinase inhibitor</td><td>imatinib, erlotinib, gefitinib</td></tr>\n<tr><td class=\"abbr\">-imus / -limus</td><td>mTOR/calcineurin-pathway immunosuppressant</td><td>tacrolimus, sirolimus, everolimus</td></tr>\n<tr><td class=\"abbr\">-tinib</td><td>Tyrosine kinase inhibitor (subclass of -nib)</td><td>imatinib, dasatinib, nilotinib</td></tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: World Health Organization, \"The use of stems in the selection of International Nonproprietary Names (INN) for pharmaceutical substances,\" WHO/EMP/RHT/TSN (who.int). The official document defining INN naming stems.</div>\n</section>\n</div>","induced":"<div>\n<nav class=\"section-nav\">\n<strong>Jump to section</strong>\n<a href=\"#di-hepatic\">Hepatotoxicity</a>\n<a href=\"#di-dermatologic\">Severe Cutaneous Reactions</a>\n<a href=\"#di-autoimmune\">Drug-Induced Lupus</a>\n<a href=\"#di-cardiac\">Cardiac</a>\n<a href=\"#di-renal\">Renal / Electrolyte</a>\n<a href=\"#di-pulmonary\">Pulmonary</a>\n<a href=\"#di-other\">Other Notable Conditions</a>\n</nav>\n<div class=\"category-intro\">\n    Recognizing that a clinical presentation might be drug-induced. Rather than a new disease. Is one of the highest-value pattern-recognition skills a pharmacist develops. This section\n    covers the classic, well-documented associations taught throughout pharmacy curricula.\n  </div>\n<section class=\"group\" id=\"di-hepatic\">\n<h2>Hepatotoxicity</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Isoniazid</div>\n<div class=\"field\"><span class=\"field-label\">Mechanism:</span> Hepatotoxic metabolites (via acetylation pathway); risk increases with age, alcohol use, and slow-acetylator phenotype.</div>\n<div class=\"field\"><span class=\"field-label\">Monitoring:</span> Baseline and periodic LFTs, especially in the first few months of therapy.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Valproic acid</div>\n<div class=\"field\"><span class=\"field-label\">Mechanism:</span> Mitochondrial toxicity; risk highest in young children and with concurrent enzyme-inducing antiepileptics.</div>\n<div class=\"field\"><span class=\"field-label\">Monitoring:</span> LFTs and ammonia level if encephalopathy is suspected.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Methotrexate</div>\n<div class=\"field\"><span class=\"field-label\">Mechanism:</span> Cumulative dose-related hepatic fibrosis with chronic use (e.g., in psoriasis/RA).</div>\n<div class=\"field\"><span class=\"field-label\">Monitoring:</span> Periodic LFTs; consider baseline hepatitis screening before starting.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Acetaminophen (overdose)</div>\n<div class=\"field\"><span class=\"field-label\">Mechanism:</span> NAPQI metabolite depletes glutathione, causing centrilobular hepatic necrosis.</div>\n<div class=\"field\"><span class=\"field-label\">Monitoring:</span> Acetaminophen level plotted on the Rumack-Matthew nomogram to guide NAC treatment decision.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Amiodarone</div>\n<div class=\"field\"><span class=\"field-label\">Mechanism:</span> Phospholipidosis and direct hepatocellular injury with chronic use.</div>\n<div class=\"field\"><span class=\"field-label\">Monitoring:</span> Baseline and every-6-month LFTs during therapy.</div>\n</div>\n<div class=\"source-line\">Source: Katzung BG, \"Basic &amp; Clinical Pharmacology,\" McGraw-Hill; FDA prescribing information for each agent (DailyMed).</div>\n</section>\n<section class=\"group\" id=\"di-dermatologic\">\n<h2>Severe Cutaneous Reactions (SJS / TEN)</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Allopurinol</div>\n<div class=\"field\"><span class=\"field-label\">Association:</span> Strong association with HLA-B*5801 allele, particularly in Han Chinese, Thai, and some other Asian populations.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Consider HLA-B*5801 screening before starting in high-risk populations per some national guidelines.</div>\n<div class=\"source-line\">Source: Hung SI, et al. \"HLA-B*5801 allele as a genetic marker for severe cutaneous adverse reactions caused by allopurinol.\" PNAS. 2005;102(11):4134\u20134139.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Carbamazepine</div>\n<div class=\"field\"><span class=\"field-label\">Association:</span> Strong association with HLA-B*1502 allele, particularly in Han Chinese and other Southeast Asian populations.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> FDA label recommends HLA-B*1502 screening in patients of Asian ancestry before starting carbamazepine.</div>\n<div class=\"source-line\">Source: Chung WH, et al. \"Medical genetics: a marker for Stevens-Johnson syndrome.\" Nature. 2004;428(6982):486. FDA prescribing information for carbamazepine (boxed warning).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Other classic SJS/TEN-associated drugs</div>\n<div class=\"field\"><span class=\"field-label\">Agents:</span> Sulfonamide antibiotics, lamotrigine (especially with rapid dose escalation or valproate co-administration), nevirapine, NSAIDs (oxicam class).</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Follow recommended slow titration schedules exactly (e.g., lamotrigine); educate patients on early mucocutaneous warning signs.</div>\n</div>\n</section>\n<section class=\"group\" id=\"di-autoimmune\">\n<h2>Drug-Induced Lupus</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Hydralazine, Procainamide, Isoniazid, Minocycline</div>\n<div class=\"field\"><span class=\"field-label\">Mechanism:</span> Thought to involve drug-modified self-proteins triggering an autoimmune response; strongly associated with slow-acetylator phenotype and anti-histone antibodies.</div>\n<div class=\"field\"><span class=\"field-label\">Clinical picture:</span> Arthralgia, myalgia, serositis. Typically without the renal/CNS involvement seen in idiopathic SLE.</div>\n<div class=\"field\"><span class=\"field-label\">Management:</span> Usually resolves within weeks to months after discontinuing the causative drug.</div>\n<div class=\"source-line\">Source: Katzung BG, \"Basic &amp; Clinical Pharmacology,\" McGraw-Hill.</div>\n</div>\n</section>\n<section class=\"group\" id=\"di-cardiac\">\n<h2>Cardiac</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">QT Prolongation / Torsades de Pointes</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Macrolides, fluoroquinolones, antipsychotics (especially haloperidol IV), ondansetron, methadone, class IA/III antiarrhythmics.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Correct hypokalemia/hypomagnesemia before and during therapy; check baseline QTc when combining multiple QT-prolonging agents.</div>\n<div class=\"source-line\">Source: CredibleMeds\u00ae QTdrugs list, maintained by AZCERT (crediblemeds.org).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Myopathy / Rhabdomyolysis</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Statins, particularly when combined with fibrates or strong CYP3A4 inhibitors.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Counsel patients to report new muscle pain/weakness; check CK if symptomatic.</div>\n</div>\n</section>\n<section class=\"group\" id=\"di-renal\">\n<h2>Renal / Electrolyte</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Hyperkalemia</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> ACE inhibitors/ARBs, potassium-sparing diuretics, NSAIDs, trimethoprim, succinylcholine.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Monitor potassium after starting or combining any of these, especially in CKD.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Nephrotoxicity</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Aminoglycosides, NSAIDs, contrast media, vancomycin (especially at high troughs), cisplatin.</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Ensure adequate hydration where relevant; monitor renal function during and after therapy.</div>\n</div>\n</section>\n<section class=\"group\" id=\"di-pulmonary\">\n<h2>Pulmonary</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Pulmonary Fibrosis</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Amiodarone, bleomycin, methotrexate, nitrofurantoin (chronic use).</div>\n<div class=\"field\"><span class=\"field-label\">Precaution:</span> Baseline and periodic pulmonary function testing/chest imaging for agents used chronically (amiodarone, long-term nitrofurantoin prophylaxis).</div>\n</div>\n</section>\n<section class=\"group\" id=\"di-other\">\n<h2>Other Notable Drug-Induced Conditions</h2>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Gingival Hyperplasia</div>\n<div class=\"field\"><span class=\"field-label\">Classic triad:</span> Phenytoin, cyclosporine, nifedipine (and other dihydropyridine CCBs).</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Photosensitivity</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Tetracyclines, fluoroquinolones, thiazide diuretics, amiodarone.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Ototoxicity</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Aminoglycosides, loop diuretics (especially IV push furosemide), high-dose salicylates, cisplatin.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Peripheral Neuropathy</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Isoniazid (preventable with pyridoxine co-administration), vincristine, prolonged metronidazole use.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Agranulocytosis</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Clozapine (requires mandatory absolute neutrophil count monitoring program), carbimazole/methimazole, sulfasalazine.</div>\n</div>\n<div class=\"int-card searchable\">\n<div class=\"pair-title\">Drug-Induced Osteoporosis</div>\n<div class=\"field\"><span class=\"field-label\">Common causes:</span> Long-term systemic corticosteroids; long-term PPI use has also been associated with fracture risk.</div>\n</div>\n<div class=\"source-line\">Source: Katzung BG, \"Basic &amp; Clinical Pharmacology,\" McGraw-Hill; FDA-approved prescribing information for each agent (DailyMed).</div>\n</section>\n</div>","tdm":"<div>\n<div class=\"disclaimer\" style=\"margin-bottom:1.5rem;\">\n    Reference ranges below are commonly cited target ranges from clinical pharmacokinetics\n    texts. Many (especially transplant immunosuppressants) are protocol- and time-post-\n    transplant\u2013dependent. Always confirm against the specific institutional protocol.\n  </div>\n<div class=\"category-intro\">\n    TDM is reserved for drugs where (1) the therapeutic index is narrow, (2) there's\n    significant inter-patient variability in pharmacokinetics, and (3) blood levels correlate\n    reasonably well with effect/toxicity. Not every drug qualifies, which is itself worth\n    remembering.\n  </div>\n<table class=\"int-table searchable\">\n<thead><tr><th>Drug</th><th>Why TDM matters</th><th>Commonly cited target range</th><th>Sampling notes</th></tr></thead>\n<tbody>\n<tr>\n<td class=\"pair\">Digoxin</td>\n<td>Narrow therapeutic index; toxicity risk rises sharply with hypokalemia or renal impairment</td>\n<td>~0.5\u20132.0 ng/mL (many heart-failure protocols target the lower end, 0.5\u20130.9 ng/mL)</td>\n<td>Trough level, at least 6\u20138 hours post-dose</td>\n</tr>\n<tr>\n<td class=\"pair\">Lithium</td>\n<td>Narrow therapeutic index; renally cleared, sensitive to dehydration/NSAID/diuretic interactions</td>\n<td>0.6\u20131.2 mEq/L (maintenance); up to 1.5 mEq/L acutely in some protocols</td>\n<td>12-hour post-dose trough level (standardized timing is essential for comparability)</td>\n</tr>\n<tr>\n<td class=\"pair\">Phenytoin</td>\n<td>Non-linear (zero-order) kinetics near the therapeutic range. Small dose changes can cause disproportionate level changes</td>\n<td>Total: 10\u201320 mcg/mL; free (unbound): 1\u20132 mcg/mL</td>\n<td>Trough level; check free level in hypoalbuminemia or renal failure</td>\n</tr>\n<tr>\n<td class=\"pair\">Carbamazepine</td>\n<td>Narrow therapeutic index; autoinduces its own metabolism over the first few weeks of therapy</td>\n<td>4\u201312 mcg/mL</td>\n<td>Trough level, after steady state is reached (~2\u20134 weeks)</td>\n</tr>\n<tr>\n<td class=\"pair\">Valproic acid</td>\n<td>Significant inter-patient variability in clearance</td>\n<td>50\u2013100 mcg/mL</td>\n<td>Trough level</td>\n</tr>\n<tr>\n<td class=\"pair\">Vancomycin</td>\n<td>Nephrotoxicity risk with excessive exposure; efficacy tied to overall drug exposure relative to pathogen susceptibility</td>\n<td>AUC24/MIC \u2265 400 is now the preferred target (per 2020 consensus guidelines); trough-only monitoring (historically 15\u201320 mg/L for serious infections) is being phased out</td>\n<td>Trough or paired levels for AUC-based (Bayesian) dosing software</td>\n</tr>\n<tr>\n<td class=\"pair\">Aminoglycosides (gentamicin, tobramycin, amikacin)</td>\n<td>Both nephrotoxic and ototoxic; efficacy is concentration-dependent</td>\n<td>Conventional dosing: peak 5\u201310 mcg/mL, trough &lt;2 mcg/mL (gentamicin/tobramycin); extended-interval dosing uses a separate nomogram</td>\n<td>Peak (~30 min post-infusion) and trough (immediately pre-dose) levels</td>\n</tr>\n<tr>\n<td class=\"pair\">Theophylline</td>\n<td>Narrow therapeutic index with many CYP1A2 drug/smoking interactions</td>\n<td>10\u201320 mcg/mL</td>\n<td>Trough level; check with any change in smoking status or interacting drug</td>\n</tr>\n<tr>\n<td class=\"pair\">Cyclosporine</td>\n<td>Narrow therapeutic index; extensive CYP3A4/P-gp interactions; risk of nephrotoxicity and rejection at either extreme</td>\n<td>Highly protocol- and transplant-type/time-dependent (commonly 100\u2013400 ng/mL range). Always use the specific transplant center's target</td>\n<td>Trough (C0) or 2-hour post-dose (C2) level depending on protocol</td>\n</tr>\n<tr>\n<td class=\"pair\">Tacrolimus</td>\n<td>Narrow therapeutic index; extensive CYP3A4 interactions; risk of nephrotoxicity and rejection at either extreme</td>\n<td>Highly protocol- and transplant-type/time-dependent (commonly 5\u201320 ng/mL range early post-transplant, lower later). Always use the specific transplant center's target</td>\n<td>Trough level, immediately pre-dose</td>\n</tr>\n<tr>\n<td class=\"pair\">Methotrexate (high-dose oncologic)</td>\n<td>Delayed clearance risks severe toxicity (mucositis, myelosuppression, renal injury)</td>\n<td>Levels plotted against a time-based nomogram (e.g., at 24/48/72 hours post-infusion) rather than a single fixed range</td>\n<td>Timed levels post-infusion to guide leucovorin (folinic acid) rescue dosing</td>\n</tr>\n</tbody>\n</table>\n<div class=\"source-line\">Source: Winter ME, \"Basic Clinical Pharmacokinetics,\" Lippincott Williams &amp; Wilkins; Rybak MJ, et al. \"Therapeutic monitoring of vancomycin: a revised consensus guideline.\" Am J Health-Syst Pharm. 2020;77(11):835\u2013864; FDA-approved prescribing information for each agent (DailyMed).</div>\n</div>"}};